import math

def min_coins(target, coins):
    dp = [math.inf] * (target + 1)
    dp[0] = 0
    for i in range(1, target + 1):
        for coin in coins:
            if coin <= i and dp[i - coin] + 1 < dp[i]:
                dp[i] = dp[i - coin] + 1
    return dp[target] if dp[target] != math.inf else -1

